//! Compatibility with real Yjs, using golden fixtures generated by `tests-compat/gen-fixtures.mjs`
//! with the Yjs release pinned in `tests-compat/package-lock.json`.
//!
//! When `YRS_COMPAT_OUT` is set, the tests also write what yrs encodes to that file, and
//! `tests-compat/check-yrs-output.mjs` decodes it with real Yjs (the other direction).

use serde_json::Value;
use std::collections::BTreeMap;
use std::sync::{Mutex, OnceLock};
use yrs::types::ToJson;
use yrs::updates::decoder::Decode;
use yrs::updates::encoder::Encode;
use yrs::{
    Any, Array, Doc, GetString, Map, OffsetKind, Options, ReadTxn, StateVector, Text, Transact,
    Update, XmlFragment,
};

fn fixtures() -> &'static Value {
    static FIXTURES: OnceLock<Value> = OnceLock::new();
    FIXTURES.get_or_init(|| {
        let path = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures/yjs-13.json");
        let json = std::fs::read_to_string(path).expect("read Yjs fixtures");
        serde_json::from_str(&json).expect("parse Yjs fixtures")
    })
}

fn fixture(name: &str) -> &'static Value {
    &fixtures()["fixtures"][name]
}

fn bytes(fixture: &Value, field: &str) -> Vec<u8> {
    let hex = fixture[field]
        .as_str()
        .unwrap_or_else(|| panic!("fixture field {} is not a string", field));
    from_hex(hex)
}

fn str_field<'a>(fixture: &'a Value, field: &str) -> &'a str {
    fixture[field]
        .as_str()
        .unwrap_or_else(|| panic!("fixture field {} is not a string", field))
}

fn from_hex(hex: &str) -> Vec<u8> {
    assert!(hex.len() % 2 == 0, "odd-length hex");
    (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).expect("hex digit"))
        .collect()
}

fn to_hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{:02x}", b)).collect()
}

/// A doc whose text offsets are UTF-16 code units, like Yjs.
fn js_doc() -> Doc {
    Doc::with_options(Options {
        offset_kind: OffsetKind::Utf16,
        ..Options::default()
    })
}

fn apply_v1(doc: &Doc, update: &[u8]) {
    let update = Update::decode_v1(update).expect("decode Yjs v1 update");
    doc.transact_mut()
        .apply_update(update)
        .expect("apply Yjs v1 update");
}

fn apply_v2(doc: &Doc, update: &[u8]) {
    let update = Update::decode_v2(update).expect("decode Yjs v2 update");
    doc.transact_mut()
        .apply_update(update)
        .expect("apply Yjs v2 update");
}

/// Records something yrs encoded, for `tests-compat/check-yrs-output.mjs` to decode with real
/// Yjs. With `check` = `"roots"`, `expect` maps root names to `{ "type", "value" }`, where type is
/// `text`, `array`, `map` or `xml` and value is what Yjs' `toJSON()`/`toString()` must return.
fn emit(name: &str, format: u8, update: &[u8], check: &str, expect: Value) {
    static OUTPUT: OnceLock<Mutex<BTreeMap<String, Value>>> = OnceLock::new();
    let Ok(path) = std::env::var("YRS_COMPAT_OUT") else {
        return;
    };
    let output = OUTPUT.get_or_init(|| Mutex::new(BTreeMap::new()));
    let mut output = output.lock().unwrap();
    output.insert(
        format!("{}_v{}", name, format),
        serde_json::json!({
            "format": format,
            "update": to_hex(update),
            "check": check,
            "expect": expect,
        }),
    );
    // Rewritten after every entry: tests run in any order and there is no "after all" hook.
    let json = serde_json::to_string_pretty(&*output).unwrap();
    std::fs::write(&path, json).expect("write YRS_COMPAT_OUT");
}

fn json_of(any: Any) -> Value {
    let mut json = String::new();
    any.to_json(&mut json);
    serde_json::from_str(&json).unwrap()
}

#[test]
fn fixtures_come_from_yjs_13() {
    let version = fixtures()["yjs"].as_str().unwrap();
    assert!(version.starts_with("13."), "fixtures from yjs {}", version);
}

#[test]
fn any_values_decode_like_yjs() {
    let f = fixture("any");
    let expected: Value = serde_json::from_str(str_field(f, "json")).unwrap();
    for (format, update) in [(1, bytes(f, "v1")), (2, bytes(f, "v2"))] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &update);
        } else {
            apply_v2(&doc, &update);
        }
        let map = doc.get_or_insert_map("m");
        let actual = json_of(map.to_json(&doc.transact()));
        assert_eq!(actual, expected, "v{}", format);
    }
}

#[test]
fn deletes_across_clients_decode_like_yjs() {
    let f = fixture("multi_client");
    for (format, update) in [(1, bytes(f, "v1")), (2, bytes(f, "v2"))] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &update);
        } else {
            apply_v2(&doc, &update);
        }
        let text = doc.get_or_insert_text("t");
        assert_eq!(
            text.get_string(&doc.transact()),
            str_field(f, "text"),
            "v{}",
            format
        );
    }
}

#[test]
fn merged_updates_are_byte_identical_to_yjs() {
    let f = fixture("merge");
    let inputs = |field: &str| -> Vec<Vec<u8>> {
        f[field]
            .as_array()
            .unwrap()
            .iter()
            .map(|h| from_hex(h.as_str().unwrap()))
            .collect()
    };
    let merged = yrs::merge_updates_v1(inputs("inputs_v1")).unwrap();
    assert_eq!(to_hex(&merged), str_field(f, "merged_v1"));
    let merged = yrs::merge_updates_v2(inputs("inputs_v2")).unwrap();
    assert_eq!(to_hex(&merged), str_field(f, "merged_v2"));
}

#[test]
fn state_vector_decodes_like_yjs() {
    let f = fixture("state_vector");
    let doc = js_doc();
    apply_v1(&doc, &bytes(f, "update_v1"));
    let sv = StateVector::decode_v1(&bytes(f, "sv")).unwrap();
    assert_eq!(sv, doc.transact().state_vector());
    assert_eq!(
        doc.get_or_insert_text("t").get_string(&doc.transact()),
        str_field(f, "text")
    );
}

#[test]
fn yrs_text_is_readable_by_yjs() {
    let doc = js_doc();
    let text = doc.get_or_insert_text("t");
    let array = doc.get_or_insert_array("a");
    {
        let mut txn = doc.transact_mut();
        text.insert(&mut txn, 0, "héllo 😀 world");
        text.remove_range(&mut txn, 1, 4);
        array.insert(&mut txn, 0, 1.5);
        array.insert(&mut txn, 1, "x");
    }
    let txn = doc.transact();
    let expected = serde_json::json!({
        "t": { "type": "text", "value": text.get_string(&txn) },
        "a": { "type": "array", "value": [1.5, "x"] },
    });
    let sv = StateVector::default();
    emit(
        "text_and_array",
        1,
        &txn.encode_state_as_update_v1(&sv),
        "roots",
        expected.clone(),
    );
    emit(
        "text_and_array",
        2,
        &txn.encode_state_as_update_v2(&sv),
        "roots",
        expected,
    );
}

#[test]
fn binary_content_round_trips_with_yjs() {
    let f = fixture("binary");
    for format in [1, 2] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &bytes(f, "v1"));
        } else {
            apply_v2(&doc, &bytes(f, "v2"));
        }
        // Roots first: get_or_insert_* takes the write lock, which an open transaction holds.
        let (array, map) = (doc.get_or_insert_array("a"), doc.get_or_insert_map("m"));
        let txn = doc.transact();
        let array = json_of(array.to_json(&txn));
        assert_eq!(array, f["array"], "array, v{}", format);
        let map = json_of(map.to_json(&txn));
        assert_eq!(map["bin"], f["map_bin"], "map, v{}", format);

        // A single writer's state re-encodes to exactly what Yjs wrote.
        let sv = StateVector::default();
        assert_eq!(
            to_hex(&txn.encode_state_as_update_v1(&sv)),
            str_field(f, "v1")
        );
        assert_eq!(
            to_hex(&txn.encode_state_as_update_v2(&sv)),
            str_field(f, "v2")
        );

        let expect = serde_json::json!({
            "a": { "type": "array", "value": f["array"] },
            "m": { "type": "map", "value": { "bin": f["map_bin"] } },
        });
        let reencoded = if format == 1 {
            txn.encode_state_as_update_v1(&sv)
        } else {
            txn.encode_state_as_update_v2(&sv)
        };
        emit("binary", format, &reencoded, "roots", expect);
    }
}

#[test]
fn binary_content_survives_a_v2_merge() {
    // A relay merging or diffing v2 updates re-encodes them; binary content must survive it.
    let f = fixture("binary");
    let merged = yrs::merge_updates_v2([bytes(f, "v2")]).unwrap();
    assert_eq!(to_hex(&merged), str_field(f, "v2"));
    let doc = js_doc();
    apply_v2(&doc, &merged);
    let array = json_of(doc.get_or_insert_array("a").to_json(&doc.transact()));
    assert_eq!(array, f["array"]);
}

#[test]
fn legacy_content_json_decodes_like_yjs() {
    // ContentJSON is what Yjs <= 12 wrote for array and map values; stored documents still hold it.
    let f = fixture("content_json");
    let expected: Value = serde_json::from_str(str_field(f, "json")).unwrap();
    for format in [1, 2] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &bytes(f, "v1"));
        } else {
            apply_v2(&doc, &bytes(f, "v2"));
        }
        let array = doc.get_or_insert_array("a");
        let txn = doc.transact();
        assert_eq!(
            array.len(&txn) as u64,
            f["len"].as_u64().unwrap(),
            "v{}",
            format
        );
        // Yjs' toJSON() turns undefined into null; yrs keeps it as Any::Undefined.
        let values: Vec<Any> = array.iter(&txn).map(|v| v.to_json(&txn)).collect();
        assert_eq!(values[2], Any::Undefined, "v{}", format);
        assert_eq!(json_of(Any::from(values)), expected, "v{}", format);

        // The JSON texts are kept as Yjs wrote them, so re-encoding is byte-identical.
        let sv = StateVector::default();
        let reencoded = if format == 1 {
            txn.encode_state_as_update_v1(&sv)
        } else {
            txn.encode_state_as_update_v2(&sv)
        };
        let original = if format == 1 { "v1" } else { "v2" };
        assert_eq!(to_hex(&reencoded), str_field(f, original), "v{}", format);
        let expect = serde_json::json!({ "a": { "type": "array", "value": expected } });
        emit("content_json", format, &reencoded, "roots", expect);
    }
}

#[test]
fn xml_hook_keeps_its_hook_name() {
    let f = fixture("xml_hook");
    for format in [1, 2] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &bytes(f, "v1"));
        } else {
            apply_v2(&doc, &bytes(f, "v2"));
        }
        let fragment = doc.get_or_insert_xml_fragment("f");
        let txn = doc.transact();
        assert_eq!(fragment.len(&txn), 2, "v{}", format);
        // Before the hook name was read, the element after the hook came out shifted
        // (`<k b="1" P="2">` instead of `<p a="1" b="2">` in v2) or the update failed (v1).
        let element = match fragment.get(&txn, 1) {
            Some(yrs::XmlOut::Element(element)) => element,
            other => panic!("expected an element after the hook, got {:?}", other),
        };
        assert_eq!(
            element.get_string(&txn),
            str_field(f, "element"),
            "v{}",
            format
        );

        // Re-encoding is byte-identical, so the hook name round-trips.
        let sv = StateVector::default();
        let reencoded = if format == 1 {
            txn.encode_state_as_update_v1(&sv)
        } else {
            txn.encode_state_as_update_v2(&sv)
        };
        let original = if format == 1 { "v1" } else { "v2" };
        assert_eq!(to_hex(&reencoded), str_field(f, original), "v{}", format);
        let expect = serde_json::json!({ "f": { "type": "xml", "value": f["fragment"] } });
        emit("xml_hook", format, &reencoded, "roots", expect);
    }
}

#[test]
fn surrogate_pair_split_across_items_decodes_like_yjs() {
    // Two items each holding half of a surrogate pair. In v2 their halves join into one 4-byte
    // character in the string column, while the item lengths still split it.
    let f = fixture("surrogate_split");
    for format in [1, 2] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &bytes(f, "v1"));
        } else {
            apply_v2(&doc, &bytes(f, "v2"));
        }
        let text = doc.get_or_insert_text("t");
        let txn = doc.transact();
        assert_eq!(text.get_string(&txn), str_field(f, "text"), "v{}", format);
        let utf16_len = f["utf16_len"].as_u64().unwrap() as u32;
        assert_eq!(text.len(&txn), utf16_len, "v{}", format);
        // Both items keep their lengths, so clocks match Yjs.
        assert_eq!(
            txn.state_vector().get(&yrs::ClientID::new(4)),
            utf16_len,
            "v{}",
            format
        );

        let sv = StateVector::default();
        let reencoded = if format == 1 {
            txn.encode_state_as_update_v1(&sv)
        } else {
            txn.encode_state_as_update_v2(&sv)
        };
        let expect = serde_json::json!({ "t": { "type": "text", "value": f["text"] } });
        emit("surrogate_split", format, &reencoded, "roots", expect);
    }
}

#[test]
fn v2_state_vectors_and_snapshots_match_yjs() {
    use yrs::updates::encoder::{Encoder, EncoderV2};
    use yrs::Snapshot;

    let f = fixture("state_vector");
    let update_v2 = bytes(f, "update_v2");

    // Yjs has one state vector format; encodeStateVectorFromUpdateV2 returns it.
    let sv = yrs::encode_state_vector_from_update_v2(&update_v2).unwrap();
    assert_eq!(to_hex(&sv), str_field(f, "sv_from_update_v2"));
    assert_eq!(to_hex(&sv), str_field(f, "sv"));
    let decoded = StateVector::decode_v2(&bytes(f, "sv")).unwrap();
    assert_eq!(decoded, StateVector::decode_v1(&bytes(f, "sv")).unwrap());

    // diffUpdateV2 takes that state vector; [0] is the empty one.
    let diff = yrs::diff_updates_v2(&update_v2, &[0]).unwrap();
    assert_eq!(to_hex(&diff), str_field(f, "diff_v2_empty_sv"));
    let diff = yrs::diff_updates_v2(&update_v2, &bytes(f, "sv")).unwrap();
    assert!(Update::decode_v2(&diff).unwrap().state_vector().is_empty());

    // Snapshots: the v2 form is a v2-style delete set and the state vector, unframed.
    let snapshot_v1 = Snapshot::decode_v1(&bytes(f, "snapshot_v1")).unwrap();
    let snapshot_v2 = Snapshot::decode_v2(&bytes(f, "snapshot_v2")).unwrap();
    assert_eq!(snapshot_v1, snapshot_v2);
    assert!(!snapshot_v2.delete_set.is_empty());
    assert_eq!(
        to_hex(&snapshot_v2.encode_v2()),
        str_field(f, "snapshot_v2")
    );
    assert_eq!(
        to_hex(&snapshot_v1.encode_v1()),
        str_field(f, "snapshot_v1")
    );

    // What yrs used to write (a whole v2 update frame) still decodes.
    let legacy = |encode: &dyn Fn(&mut EncoderV2)| {
        let mut encoder = EncoderV2::new();
        encode(&mut encoder);
        encoder.to_vec()
    };
    let legacy_sv = legacy(&|e| decoded.encode(e));
    assert_ne!(legacy_sv, bytes(f, "sv"));
    assert_eq!(StateVector::decode_v2(&legacy_sv).unwrap(), decoded);
    let legacy_snapshot = legacy(&|e| snapshot_v2.encode(e));
    assert_eq!(Snapshot::decode_v2(&legacy_snapshot).unwrap(), snapshot_v2);
}

#[test]
fn subdocument_options_round_trip_with_yjs() {
    let f = fixture("subdoc");
    let subdocs = |doc: &Doc| -> Vec<(String, Doc)> {
        let map = doc.get_or_insert_map("m");
        let txn = doc.transact();
        ["sub", "sub2"]
            .iter()
            .map(|key| match map.get(&txn, key) {
                Some(yrs::Out::YDoc(sub)) => (key.to_string(), sub),
                other => panic!("m.{} is not a subdocument: {:?}", key, other),
            })
            .collect()
    };
    for format in [1, 2] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &bytes(f, "v1"));
        } else {
            apply_v2(&doc, &bytes(f, "v2"));
        }
        let subs = subdocs(&doc);
        let (_, sub) = &subs[0];
        assert_eq!(sub.guid().as_ref(), "sub-guid");
        assert!(!sub.auto_load() && !sub.should_load(), "v{}", format);
        let meta = sub.meta().expect("meta of a Yjs subdocument");
        assert_eq!(
            json_of(meta),
            serde_json::json!({ "title": "x" }),
            "v{}",
            format
        );
        let (_, sub2) = &subs[1];
        // Yjs: shouldLoad = opts.shouldLoad || opts.autoLoad
        assert!(sub2.auto_load() && sub2.should_load(), "v{}", format);
        assert_eq!(sub2.meta(), None);

        let sv = StateVector::default();
        let txn = doc.transact();
        let reencoded = if format == 1 {
            txn.encode_state_as_update_v1(&sv)
        } else {
            txn.encode_state_as_update_v2(&sv)
        };
        let expect = serde_json::json!({ "m": {
            "sub": { "guid": "sub-guid", "autoLoad": false, "shouldLoad": false, "meta": { "title": "x" } },
            "sub2": { "guid": "sub-guid-2", "autoLoad": true, "shouldLoad": true, "meta": null },
        }});
        emit("subdoc", format, &reencoded, "subdocs", expect);
    }
}

#[test]
fn yrs_subdocuments_are_not_loaded_eagerly_by_yjs() {
    let doc = js_doc();
    let map = doc.get_or_insert_map("m");
    let sub = Doc::with_options(Options {
        guid: "yrs-sub".into(),
        ..Options::default()
    });
    assert!(sub.should_load(), "a new local document should load");
    map.insert(&mut doc.transact_mut(), "sub", sub);
    let txn = doc.transact();
    let update = txn.encode_state_as_update_v1(&StateVector::default());

    // A peer receiving the reference must not load it unless it is marked autoLoad.
    let remote = js_doc();
    apply_v1(&remote, &update);
    let remote_map = remote.get_or_insert_map("m");
    match remote_map.get(&remote.transact(), "sub") {
        Some(yrs::Out::YDoc(sub)) => assert!(!sub.should_load()),
        other => panic!("not a subdocument: {:?}", other),
    }
    let expect = serde_json::json!({ "m": {
        "sub": { "guid": "yrs-sub", "autoLoad": false, "shouldLoad": false, "meta": null },
    }});
    emit("yrs_subdoc", 1, &update, "subdocs", expect);
}

#[test]
fn relative_positions_match_yjs() {
    use yrs::{Assoc, IndexScope, IndexedSequence, StickyIndex, ID};

    let f = fixture("relative_position");
    let doc = js_doc();
    apply_v1(&doc, &bytes(f, "doc_v1"));
    let text = doc.get_or_insert_text("t");
    let txn = doc.transact();

    // The caret at the end of the text: Yjs gives a position for the type itself.
    let end = text
        .sticky_index(&txn, 3, Assoc::After)
        .expect("end position");
    assert_eq!(to_hex(&end.encode_v1()), str_field(f, "end_after"));
    let decoded = StickyIndex::decode_v1(&bytes(f, "end_after")).unwrap();
    assert_eq!(decoded.get_offset(&txn).map(|o| o.index), Some(3));

    let mid = text.sticky_index(&txn, 1, Assoc::Before).unwrap();
    assert_eq!(to_hex(&mid.encode_v1()), str_field(f, "mid_before"));

    // Positions stored before Yjs added assoc have no trailing assoc; Yjs reads them as "after".
    let legacy = StickyIndex::decode_v1(&bytes(f, "legacy_no_assoc")).unwrap();
    assert_eq!(legacy.assoc, Assoc::After);
    let item = ID::new(yrs::ClientID::new(7), 1);
    assert_eq!(legacy.scope(), &IndexScope::Relative(item));
}

#[test]
fn clocks_above_2_pow_31_survive_v2_like_yjs() {
    let f = fixture("big_clock");
    let from_v1 = Update::decode_v1(&bytes(f, "v1")).unwrap();
    let from_v2 = Update::decode_v2(&bytes(f, "v2")).expect("decode Yjs v2 with big clocks");
    assert_eq!(from_v1.encode_v1(), from_v2.encode_v1());
    // v1 -> v2 like Yjs' convertUpdateFormatV1ToV2, byte for byte
    assert_eq!(to_hex(&from_v1.encode_v2()), str_field(f, "v2"));
    // ...and back: the second item's origin, clock 2^31 + 6, is intact
    assert_eq!(to_hex(&from_v2.encode_v1()), str_field(f, "v1"));
}

#[test]
fn unusual_json_numbers_in_formats_decode_like_yjs() {
    // JSON.stringify(1e19) is "10000000000000000000", beyond i64.
    let f = fixture("json_edge");
    let expected: Value = serde_json::from_str(str_field(f, "delta")).unwrap();
    for format in [1, 2] {
        let doc = js_doc();
        if format == 1 {
            apply_v1(&doc, &bytes(f, "v1"));
        } else {
            apply_v2(&doc, &bytes(f, "v2"));
        }
        let text = doc.get_or_insert_text("t");
        let txn = doc.transact();
        let delta: Vec<Value> = text
            .diff(&txn, yrs::types::text::YChange::identity)
            .into_iter()
            .map(|d| {
                let insert = match d.insert {
                    yrs::Out::Any(Any::String(s)) => Value::String(s.to_string()),
                    yrs::Out::Any(any) => json_of(any),
                    other => panic!("unexpected insert {:?}", other),
                };
                let mut entry = serde_json::json!({ "insert": insert });
                if let Some(attrs) = d.attributes {
                    let attrs: serde_json::Map<String, Value> = attrs
                        .iter()
                        .map(|(k, v)| (k.to_string(), json_of(v.clone())))
                        .collect();
                    entry["attributes"] = Value::Object(attrs);
                }
                entry
            })
            .collect();
        // JavaScript has one number type, so compare numbers by value.
        fn numbers_as_f64(v: Value) -> Value {
            match v {
                Value::Number(n) => serde_json::json!(n.as_f64().unwrap()),
                Value::Array(a) => Value::Array(a.into_iter().map(numbers_as_f64).collect()),
                Value::Object(o) => {
                    Value::Object(o.into_iter().map(|(k, v)| (k, numbers_as_f64(v))).collect())
                }
                other => other,
            }
        }
        assert_eq!(
            numbers_as_f64(Value::Array(delta)),
            numbers_as_f64(expected.clone()),
            "v{}",
            format
        );
    }
}

/// Wraps an encoded awareness update the way y-protocols frames it: the awareness tag, then the
/// update as a length-prefixed buffer.
fn awareness_message(update: &[u8]) -> Vec<u8> {
    use yrs::encoding::write::Write;
    use yrs::updates::encoder::{Encoder, EncoderV1};
    let mut encoder = EncoderV1::new();
    encoder.write_var(yrs::sync::protocol::MSG_AWARENESS);
    encoder.write_buf(update);
    encoder.to_vec()
}

#[test]
fn sync_messages_are_byte_identical_to_y_protocols() {
    use yrs::sync::{Message, SyncMessage};
    let f = fixture("protocol");

    // The same document Yjs framed: client 15 with the text "hi".
    let doc = Doc::with_client_id(15);
    doc.get_or_insert_text("t")
        .insert(&mut doc.transact_mut(), 0, "hi");
    let txn = doc.transact();
    let update = txn.encode_state_as_update_v1(&StateVector::default());

    let step1 = Message::Sync(SyncMessage::SyncStep1(txn.state_vector()));
    let step2 = Message::Sync(SyncMessage::SyncStep2(update.clone()));
    let sync_update = Message::Sync(SyncMessage::Update(update));
    for (field, message) in [
        ("sync_step1", step1),
        ("sync_step2", step2),
        ("sync_update", sync_update),
    ] {
        let yjs = bytes(f, field);
        assert_eq!(to_hex(&message.encode_v1()), to_hex(&yjs), "{}", field);
        let decoded = Message::decode_v1(&yjs).unwrap_or_else(|e| panic!("{}: {}", field, e));
        assert_eq!(decoded, message, "{}", field);
    }
}

#[test]
fn awareness_updates_decode_and_frame_like_y_protocols() {
    use yrs::sync::{AwarenessUpdate, Message};
    let f = fixture("protocol");

    let update = AwarenessUpdate::decode_v1(&bytes(f, "awareness")).unwrap();
    let entry = &update.clients[&yrs::ClientID::new(15)];
    assert_eq!(entry.clock, 1);
    let state: Value = serde_json::from_str(&entry.json).unwrap();
    assert_eq!(
        state,
        serde_json::json!({ "user": { "name": "a", "n": 1.5 } })
    );
    // One client, so the encoding is canonical.
    assert_eq!(to_hex(&update.encode_v1()), str_field(f, "awareness"));

    // Clearing the local state sends the JSON `null` with the next clock.
    let cleared = AwarenessUpdate::decode_v1(&bytes(f, "awareness_null")).unwrap();
    let entry = &cleared.clients[&yrs::ClientID::new(15)];
    assert_eq!((entry.clock, &*entry.json), (2, "null"));
    assert_eq!(to_hex(&cleared.encode_v1()), str_field(f, "awareness_null"));

    // yrs' own Awareness writes the same bytes for the same state (given as the raw JSON, since
    // serde_json sorts object keys and Yjs keeps insertion order).
    let mut awareness = yrs::sync::Awareness::new(Doc::with_client_id(15));
    awareness.set_local_state_raw(r#"{"user":{"name":"a","n":1.5}}"#);
    assert_eq!(
        to_hex(&awareness.update().unwrap().encode_v1()),
        str_field(f, "awareness")
    );
    // Like the fixture (`encodeAwarenessUpdate(aw, [15])`), name the client: `update()` leaves
    // out cleared states.
    awareness.clean_local_state();
    let client = yrs::ClientID::new(15);
    assert_eq!(
        to_hex(&awareness.update_with_clients([client]).unwrap().encode_v1()),
        str_field(f, "awareness_null")
    );

    // Framed as a protocol message, both directions agree on the bytes.
    let framed = awareness_message(&bytes(f, "awareness"));
    assert_eq!(Message::Awareness(update.clone()).encode_v1(), framed);
    assert_eq!(
        Message::decode_v1(&framed).unwrap(),
        Message::Awareness(update)
    );
}
